function reasonFor(surface: CoverageSurface, locator: string): string {
  switch (surface) {
    case "db":
      return `${locator} is an exact current plaintext database location whose `
        + "future key ownership and plaintext necessity have not yet been triaged.";
    case "wire":
      return `${locator} is an exact current plaintext transport contract whose `
        + "future encrypted DTO boundary has not yet been triaged.";
    default:
      return `${locator} is an exact current plaintext ${surface} boundary whose `
        + "future encryption classification has not yet been triaged.";
  }
}

function evidenceGapFor(surface: CoverageSurface, locator: string): string {
  switch (surface) {
    case "db":
      return `${locator} has no implemented ciphertext schema repository or `
        + "negative plaintext-snapshot evidence.";
    case "wire":
      return `${locator} has no implemented ciphertext wire schema or negative `
        + "plaintext-payload evidence.";
    default:
      return `${locator} has no implemented ciphertext boundary or negative `
        + "plaintext-leak evidence.";
  }
}

const DB_OBJECT_BASELINE_DEBT_MANIFEST: readonly BaselineManifestEntry[] =
  [...new Set(
    BASELINE_DEBT_MANIFEST
      .filter(([, surface, locator]) =>
        surface === "db"
        && locator.startsWith("public.")
        && locator.split(".").length === 3
      )
      .map(([, , locator]) => locator.split(".").slice(0, 2).join(".")),
  )]
    .sort()
    .map((locator) => [
      `db.object.${locator}`,
      "db",
      locator,
      "packages/db",
    ]);

const COMPLETE_BASELINE_DEBT_MANIFEST: readonly BaselineManifestEntry[] = [
  ...BASELINE_DEBT_MANIFEST,
  ...DB_OBJECT_BASELINE_DEBT_MANIFEST,
];

/**
 * Immutable Wave 0 grandfathered debt snapshot.
 *
 * New observations must be classified; appending current debt elsewhere does
 * not extend this snapshot. Its exact count and fingerprint are independently
 * locked by the repository inventory verification.
 */
export const WAVE_0_FROZEN_BASELINE_DEBT: readonly EncryptionBaselineDebt[] =
  [
    ...COMPLETE_BASELINE_DEBT_MANIFEST.map(
      ([observationId, surface, locator, owner]) => ({
        id: `debt.${observationId}`,
        surface,
        locator,
        owner,
        reason: reasonFor(surface, locator),
        remediationState: "untriaged" as const,
        releaseImpact: "blocks_whole_product_claim" as const,
        evidenceGap: evidenceGapFor(surface, locator),
      }),
    ),
    ...WAVE_0_RAW_DATABASE_WRITER_DEBT,
  ];

export const CURRENT_FROZEN_BASELINE_DEBT: readonly EncryptionBaselineDebt[] = [
  ...WAVE_0_FROZEN_BASELINE_DEBT,
];

